CREATE TABLE schema_version(version INT PRIMARY KEY, checksum CHAR(64) NOT NULL, instalada_en TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB;
CREATE TABLE administradores(id BIGINT PRIMARY KEY AUTO_INCREMENT, usuario VARCHAR(64) COLLATE utf8mb4_bin NOT NULL UNIQUE, nombre VARCHAR(255) NOT NULL, hash BINARY(32) NOT NULL, salt BINARY(16) NOT NULL, iteraciones INT NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE, fallos INT NOT NULL DEFAULT 0, bloqueado_hasta DATETIME(6) NULL) ENGINE=InnoDB;
CREATE TABLE usuarios(id VARCHAR(128) COLLATE utf8mb4_bin PRIMARY KEY, nombre VARCHAR(255) NOT NULL, email VARCHAR(254) NOT NULL, limite INT NOT NULL, multa DECIMAL(19,2) NOT NULL DEFAULT 0, CHECK(limite>0), CHECK(multa>=0)) ENGINE=InnoDB;
CREATE TABLE libros(id VARCHAR(128) COLLATE utf8mb4_bin PRIMARY KEY, titulo VARCHAR(512) NOT NULL, autor VARCHAR(255) NOT NULL, isbn VARCHAR(13) NOT NULL, anio INT NOT NULL, categoria VARCHAR(128) NOT NULL, CHECK(anio>=1000)) ENGINE=InnoDB;
CREATE TABLE prestamos(id VARCHAR(128) COLLATE utf8mb4_bin PRIMARY KEY, usuario_id VARCHAR(128) COLLATE utf8mb4_bin NOT NULL, libro_id VARCHAR(128) COLLATE utf8mb4_bin NOT NULL, fecha DATE NOT NULL, esperada DATE NOT NULL, fecha_real DATE NULL, estado ENUM('ACTIVO','DEVUELTO','CANCELADO') NOT NULL, libro_activo VARCHAR(128) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN estado='ACTIVO' THEN libro_id ELSE NULL END) STORED, UNIQUE(libro_activo), FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE RESTRICT, FOREIGN KEY(libro_id) REFERENCES libros(id) ON DELETE RESTRICT, CHECK(esperada>=fecha), CHECK((estado='ACTIVO' AND fecha_real IS NULL) OR (estado<>'ACTIVO' AND fecha_real IS NOT NULL AND fecha_real>=fecha)), INDEX(usuario_id,estado)) ENGINE=InnoDB;
CREATE TABLE reservas(id VARCHAR(128) COLLATE utf8mb4_bin PRIMARY KEY, usuario_id VARCHAR(128) COLLATE utf8mb4_bin NOT NULL, libro_id VARCHAR(128) COLLATE utf8mb4_bin NOT NULL, fecha DATE NOT NULL, orden BIGINT NOT NULL UNIQUE, estado ENUM('PENDIENTE','NOTIFICADA','CANCELADA','ATENDIDA') NOT NULL, usuario_cola VARCHAR(128) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN estado IN ('PENDIENTE','NOTIFICADA') THEN usuario_id ELSE NULL END) STORED, libro_cola VARCHAR(128) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN estado IN ('PENDIENTE','NOTIFICADA') THEN libro_id ELSE NULL END) STORED, UNIQUE(usuario_cola,libro_cola), FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE RESTRICT, FOREIGN KEY(libro_id) REFERENCES libros(id) ON DELETE RESTRICT, INDEX(libro_id,estado,orden)) ENGINE=InnoDB;
CREATE TABLE secuencias(nombre VARCHAR(32) PRIMARY KEY, siguiente BIGINT NOT NULL CHECK(siguiente>0)) ENGINE=InnoDB;
INSERT INTO secuencias VALUES('prestamo',1),('reserva',1),('orden',1);
CREATE TABLE operaciones(id CHAR(36) PRIMARY KEY, administrador_id BIGINT NOT NULL, tipo VARCHAR(64) NOT NULL, entidad VARCHAR(128) NULL, creada_en TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), FOREIGN KEY(administrador_id) REFERENCES administradores(id)) ENGINE=InnoDB;
CREATE TABLE importaciones(checksum CHAR(64) PRIMARY KEY, libros INT NOT NULL, usuarios INT NOT NULL, prestamos INT NOT NULL, reservas INT NOT NULL, creada_en TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB;
